class UniversalTokenizer {
  private val stringTokenizer = StringTokenizer()
  private val numericTokenizer = NumericTokenizer()
  private val temporalTokenizer = TemporalTokenizer()

  def tokenize(value: String): Token = stringTokenizer.tokenize(value)

  def tokenize(value: Array[Byte]): Token = stringTokenizer.tokenizeBytes(value)

  def tokenize(value: Int): Token = numericTokenizer.tokenizeInt(value)

  def tokenize(value: Long): Token = numericTokenizer.tokenizeLong(value)

  def tokenize(value: Double): Token = numericTokenizer.tokenizeDouble(value)

  def tokenize(value: BigDecimal): Token = numericTokenizer.tokenize(value)

  def tokenize(value: LocalDateTime): Token = temporalTokenizer.tokenize(value)

  def tokenize(value: LocalDate): Token = temporalTokenizer.tokenizeDate(value)

  def tokenizeNull: Token = Token("NULL", TokenType.Null)

  def tokenize(value: Tokenizable): Token =
    Token(value.toToken, TokenType.Structured)

  def tokenizeAny(value: Any): Token = value match {
    case null => tokenizeNull
    case t: Tokenizable => tokenize(t)
    case s: String => tokenize(s)
    case b: Array[Byte] => tokenize(b)
    case i: Int => tokenize(i)
    case l: Long => tokenize(l)
    case d: Double => tokenize(d)
    case bd: BigDecimal => tokenize(bd)
    case dt: LocalDateTime => tokenize(dt)
    case d: LocalDate => tokenize(d)
    case other => Token(other.toString, TokenType.String, Map("fallback" -> true))
  }
}

